parameters.functionCode:
const item = $input.first().json;
const payload = item.body && typeof item.body === 'object' ? item.body : item;
const appointment = payload.appointment || payload;
if (!appointment || typeof appointment !== 'object') {
  return [{ json: { error: 'missing appointment', patientEmail: '', patientName: '', patientPhone: '' } }];
}
const hoursBefore = payload.metadata?.hoursBefore || 24;
const p = appointment.patientId;
const patientInfo = p && typeof p === 'object' && !Array.isArray(p) ? p : {};
const id = appointment._id || appointment.id;
return [{
  json: {
    patientEmail: patientInfo.email || appointment.patientEmail || '',
    patientName: `${patientInfo.firstName || ''} ${patientInfo.lastName || ''}`.trim() || 'Patient',
    patientPhone: patientInfo.phone || '',
    doctorName: appointment.doctorName || 'Your Doctor',
    appointmentDate: appointment.date || '',
    appointmentTime: appointment.time || '',
    appointmentType: appointment.type || 'checkup',
    location: appointment.location || 'Medical Center',
    isVideoCall: !!appointment.isVideoCall,
    hoursBefore,
    appointmentId: id != null ? String(id) : ''
  }
}];

parameters.text:
Dear {{ $json.patientName }},

This is a friendly reminder about your upcoming appointment:

Appointment Details:
- Date: {{ $json.appointmentDate }}
- Time: {{ $json.appointmentTime }}
- Type: {{ $json.appointmentType }}
- Doctor: {{ $json.doctorName }}
- Location: {{ $json.location }}

{{ $json.isVideoCall ? 'This is a video call appointment. Check your email for the meeting link.\n\n' : '' }}Please remember to:
- Arrive 15 minutes early
- Bring your ID and insurance card
- Bring any relevant medical records
- Take your regular medications unless instructed otherwise

If you need to reschedule or cancel, please call us as soon as possible.

We look forward to seeing you!

MediFollow Team

parameters.functionCode:
const data = $node['Prepare Reminder Data'].json;
if (data.patientPhone) {
  return [{
    json: {
      to: data.patientPhone,
      message: 'Reminder: Your appointment with ' + data.doctorName + ' is tomorrow at ' + data.appointmentTime + '. Reply CANCEL to reschedule.'
    }
  }];
}
return [{ json: { skippedSms: true } }];

const data = $node['Prepare Reminder Data'].json;
return [{
  json: {
    success: true,
    message: 'Appointment reminders sent successfully',
    timestamp: new Date().toISOString(),
    appointmentId: data.appointmentId,
    hoursBefore: data.hoursBefore
  }
}];
